-- Deal box: one side suggests the Admin, the other side agrees, then the Admin is asked.
-- No alerts reach a suggested Admin until the buyer and the seller both agree. Replaces only the notification trigger; no data changes.
DROP TRIGGER IF EXISTS wm_notify_deal_event;
CREATE TRIGGER wm_notify_deal_event AFTER INSERT ON wm_deal_events
BEGIN
 INSERT OR IGNORE INTO wm_notifications(user_id,actor_id,category,event_key,kind,title,target_type,target_id,created_at,alert_enabled)
 SELECT u.id,NEW.user_id,'deal_updates','deal:event:'||NEW.id,'deal_update',CASE WHEN NEW.action='requested' THEN 'New deal request' WHEN NEW.action='confirm' AND d.admin_id IS NULL THEN 'Seller accepted · the deal box is open' WHEN NEW.action='admin_proposed' THEN 'An Admin was suggested · agree in the deal box' WHEN NEW.action='admin_requested' AND u.id=d.admin_id THEN 'New deal request — accept to join' WHEN NEW.action='admin_requested' THEN 'Both agreed · the Admin was asked to join' WHEN NEW.action='admin_declined' THEN 'The Admin said no · choose another Admin' WHEN NEW.action='withdraw' THEN 'Deal cancelled' WHEN NEW.action='confirm' AND d.buyer_ok=1 AND d.seller_ok=1 AND u.id=d.admin_id THEN 'New deal request' WHEN NEW.action='confirm' AND d.buyer_ok=1 AND d.seller_ok=1 THEN 'Both agreed on the Admin' WHEN NEW.action='confirm' THEN 'Deal terms agreed' WHEN NEW.action='admin_changed' THEN 'Another Admin was suggested' WHEN NEW.action IN ('accept','activate') THEN 'Admin accepted the deal' WHEN NEW.action='reject' THEN 'Admin rejected the deal' WHEN NEW.action LIKE 'chat:%' THEN 'New deal message' WHEN NEW.action='payment_sent' THEN 'Buyer sent the money' WHEN NEW.action='payment_received' THEN 'Admin received the money' WHEN NEW.action='delivered' THEN 'Seller handed over the ID' WHEN NEW.action='buyer_confirmed' THEN 'Buyer got the ID' WHEN NEW.action IN ('seller_paid','finalize') THEN 'Deal completed' WHEN NEW.action='dispute' THEN 'Dispute raised' WHEN NEW.action IN ('resolve_dispute','resolve_redeliver') THEN 'Dispute resolved' WHEN NEW.action='cancel' THEN 'Deal cancelled' WHEN NEW.action='cancel_requested' THEN 'Cancellation requested' WHEN NEW.action='handover_submitted' THEN 'Login details sent securely' ELSE 'Deal status updated' END,'deal',NEW.deal_id,NEW.created_at,
 COALESCE((SELECT enabled FROM wm_notification_preferences WHERE user_id=u.id AND category='deal_updates'),1)*(1)
 FROM wm_deals d JOIN users u ON u.id IN (d.buyer_id,d.seller_id,d.admin_id) WHERE d.id=NEW.deal_id AND u.id!=NEW.user_id
  AND (u.id IN (d.buyer_id,d.seller_id) OR d.mode='direct' OR (d.buyer_ok=1 AND d.seller_ok=1) OR d.status NOT IN ('proposed','awaiting_seller','awaiting_admin','open','admin_proposed'))
  AND NOT (u.id=d.admin_id AND u.id NOT IN (d.buyer_id,d.seller_id) AND (d.status IN ('open','admin_proposed') OR (NEW.action LIKE 'chat:%' AND d.status='awaiting_admin')));
END;
